import { appendSplitCsv, copySplitFile, ensureSplitFolder, listSplitFolder, splitPath } from "~/core/persistence/splitFiles";

/**
 * gen3's `logData`, `logCopy` and `loadCsvFile` (the helpers above its component in
 * `scripts/frontend.js`), on the splits IPC instead of `require("fs")` (plan 2.4 /
 * 1.6). Generated by tools/port/lift-gen3.py, so the header string and path segments
 * are byte-for-byte gen3's. Since 2026-10-14 only the simple CSV is written, named
 * `<letter>-<test_run_>?<Species>-<id>.csv` (no `-simple`). gen3 keeps its own `logCopy`,
 * which numbers a finished run by listing `finishes/` and copies nothing for a
 * test run (known-legacy-bugs.md #21).
 *
 * The legacy file also created `splits/`, `splits/Emerald` and `splits/FireRed` when
 * it loaded (and `storage/`, for the dead Storage.json object, which is not
 * reproduced), which is done here.
 */
for (const folder of ['', 'Emerald', 'FireRed']) {
    void ensureSplitFolder(folder);
}

export function logData(gameName, gameName_path, str, file_name, starter, testStatus, evolution, evolution_label, unique_run_identifier, is_new_run) {
        const testStatusText = testStatus ? "test_run_" : "";
        // The starter parameter already contains the correct split file name (calculated by getSplitFileName())
        // Use unique_run_identifier instead of file_name (attempt_number) for attempts folder
        const run_identifier = unique_run_identifier || file_name;
        // The legacy read `gameName` off the mounted instance's `game` computed here, which
        // is what both call sites pass as `gameName_path` (tools/port/lift-gen3.py).
        const dirPath = splitPath(gameName_path, starter, "attempts");
        const filePath = splitPath(dirPath, `${gameName}-${testStatusText}${starter}-${run_identifier}.csv`);
        const header = "player_name," +
                    "pokemon," +
                    "trainer_name," +
                    "real_time_hmmss," +
                    "resets," +
                    "blackouts," +
                    "level," +
                    "game_time," +
                    "battle_duration," +
                    "move1," +
                    "move2," +
                    "move3," +
                    "move4,\n"
        return appendSplitCsv(filePath, header, str);
}

export async function logCopy(gameName, gameName_path, unique_run_identifier, starter, evolution, evolution_label, is_new_run, testStatus, loggedRunsManager) {
    if (evolution == true) {
        starter = evolution_label;
    }
    const testStatusText = testStatus ? "test_run_" : "";
    var dirPathAttempts = splitPath(gameName_path, starter, "attempts");
    var dirPathFinishes = splitPath(gameName_path, starter, "finishes");
    
    // Calculate the next finished_run_count by checking existing files in finishes folder
    let nextFinishedRunCount = 1;
    try {
        {
            // readdirSync over the splits IPC; a missing folder lists as empty, which is
            // what the existsSync guard made it.
            const files = await listSplitFolder(dirPathFinishes);
            // Look for files matching the pattern: ${gameName}-${starter}-${number}.csv, and the
            // `-simple.csv` names finished runs had before 2026-10-14, so the numbering carries on.
            // (test runs are not copied to finishes, so we don't need to check for test_run_ prefix)
            const pattern = new RegExp(`^${gameName}-${starter}-(\\d+)(-simple)?\\.csv$`);
            const numbers = files
                .map(file => {
                    const match = file.match(pattern);
                    return match ? parseInt(match[1], 10) : null;
                })
                .filter(num => num !== null);
            
            if (numbers.length > 0) {
                nextFinishedRunCount = Math.max(...numbers) + 1;
            }
        }
    } catch (error) {
        console.error('[logCopy] Error calculating next finished run count:', error);
    }
    
    await ensureSplitFolder(dirPathFinishes);
    // Copy the file using unique_run_identifier from attempts folder and nextFinishedRunCount for finishes folder
    // Note: test runs are not copied to finishes folder
    if (!testStatus) {
        await copySplitFile(
            splitPath(dirPathAttempts, `${gameName}-${testStatusText}${starter}-${unique_run_identifier}.csv`),
            splitPath(dirPathFinishes, `${gameName}-${starter}-${nextFinishedRunCount}.csv`));
    }
}

/** The file picker behind "Load Splits": the File System Access API is Chromium's, not Node's. */
export async function loadCsvFile() {
    const file = await window.showOpenFilePicker({
        id: "SplitsFolder",
        types: [{
            description: "Split files",
            accept: { "text/csv": [".csv"] }
        }]
    });
    const contents = await file[0].getFile();
    const text = await contents.text();
    return text;
}
